package ma.lias.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="material_distributions")
public class MaterialDistribution { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="material_id") private Long materialId; @Column(name="member_id") private Long memberId; private int quantity; @Column(name="distributed_at") private LocalDateTime distributedAt = LocalDateTime.now(); @Column(name="distributed_by") private Long distributedBy; public Long getId(){return id;} public void setId(Long id){this.id=id;} public Long getMaterialId(){return materialId;} public void setMaterialId(Long materialId){this.materialId=materialId;} public Long getMemberId(){return memberId;} public void setMemberId(Long memberId){this.memberId=memberId;} public int getQuantity(){return quantity;} public void setQuantity(int quantity){this.quantity=quantity;} public LocalDateTime getDistributedAt(){return distributedAt;} public void setDistributedAt(LocalDateTime distributedAt){this.distributedAt=distributedAt;} public Long getDistributedBy(){return distributedBy;} public void setDistributedBy(Long distributedBy){this.distributedBy=distributedBy;} }
